button.bind.anchorText:
export function bindBagButton(button: HTMLButtonElement): void {
  button.addEventListener('click', () => {
    void openBagPanel();
  });
}

panel.open.anchorText:
  panel = document.createElement('div');
  panel.className = 'bag-panel';
  await ensureAssets();
  await refreshList();
}

panel.refresh.anchorText:
export async function refreshList(): Promise<void> {
  const items = await readItems();
  if (!panel) return;
  panel.replaceChildren(...items.map(item => renderItem(item)));
}

panel.read.anchorText:
async function readItems(): Promise<BagItem[]> {
  const items = await loadBag();
  if (items.length > 0) return items;
  return loadFallback();
}

repo.load.anchorText:
  const cached = cache.get('bag');
  if (cached) return cached;
  const response = await fetch('/api/bag');
  const items = (await response.json()) as BagItem[];
  cache.set('bag', items);
  return items;
}

repo.fallback.anchorText:
export async function loadFallback(): Promise<BagItem[]> {
  return [];
}
